--
-- Dumping data for table `news`
--

INSERT INTO `news` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `image`, `is_published`, `published_at`, `created_at`, `updated_at`) VALUES
(1, 'Conveyor Uni Express Expands Door-to-Door Collection Network Across Bangladesh', 'cux-expands-door-to-door-collection-network', 'Company News', 'Recruiting local couriers with extensive neighborhood knowledge ensures industry-leading first time delivery hit rates for all clients.', 'Conveyor Uni Express (CUX) - Courier and Freight Worldwide - has expanded its nationwide door-to-door collection and delivery infrastructure. With couriers recruited from within local areas, our staff delivers unmatched localized navigation, allowing detour deliveries if recipients are near their workplace, up to three delivery attempts, and safe place collection options for total convenience.', 'assets/images/news/courier-network.jpg', 1, '2026-09-18 07:28:45', '2026-09-20 01:28:45', '2026-09-20 01:28:45'),
(2, 'CUX Celebrates Decades of Leadership in Project Shipping for Bangladesh Development Projects', 'cux-celebrates-leadership-project-shipping', 'Project Logistics', 'As the premier concern of Conveyor Group, CUX remains the number one choice for government project cargo and outsized freight.', 'Conveyor Uni Express continues to lead Bangladesh in Project Shipping, executing critical turnkey transportation for major infrastructure, power plants, bridge projects, and civil developments. With specialized barge chartering, heavy crane mobilizations, and dedicated customs brokerage at Chittagong and Mongla ports, CUX delivers certainty to Bangladesh’s economic growth.', 'assets/images/news/project-shipping.jpg', 1, '2026-09-15 07:28:45', '2026-09-20 01:28:45', '2026-09-20 01:28:45'),
(3, 'Enhanced Cold-Chain Protocols for Clinical Trial and Pharmaceutical Cargo at Dhaka Airport', 'enhanced-cold-chain-pharma-dhaka-airport', 'Specialized Cargo', 'Dedicated bonded storage at HSIA Dhaka Airport provides calibrated temperature zones for biological specimens and life-saving medicines.', 'With our own dedicated warehouse facility at Dhaka Airport, Conveyor Uni Express offers state-of-the-art cold-chain logistics for pharmaceutical manufacturers, research institutes, and clinical trials. Featuring real-time temperature data logging, priority customs clearance, and dry ice replenishment, your biological cargo is guaranteed unbroken integrity from origin to destination.', 'assets/images/news/cold-chain-pharma.jpg', 1, '2026-09-12 07:28:45', '2026-09-20 01:28:45', '2026-09-20 01:28:45');

