--
-- Table structure for table `shipments`
--

CREATE TABLE `shipments` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `tracking_number` varchar(255) NOT NULL,
  `reference_no` varchar(255) DEFAULT NULL,
  `service_type` varchar(255) NOT NULL DEFAULT 'Air Express',
  `sender_name` varchar(255) DEFAULT NULL,
  `sender_email` varchar(255) DEFAULT NULL,
  `sender_phone` varchar(255) DEFAULT NULL,
  `sender_address` text DEFAULT NULL,
  `sender_city` varchar(255) DEFAULT NULL,
  `sender_country` varchar(255) DEFAULT NULL,
  `receiver_name` varchar(255) NOT NULL,
  `receiver_email` varchar(255) DEFAULT NULL,
  `receiver_phone` varchar(255) NOT NULL,
  `receiver_address` text NOT NULL,
  `receiver_city` varchar(255) NOT NULL,
  `receiver_country` varchar(255) NOT NULL,
  `weight` decimal(8,2) NOT NULL DEFAULT 1.00,
  `pieces` int(11) NOT NULL DEFAULT 1,
  `dimensions` varchar(255) DEFAULT NULL,
  `declared_value` decimal(10,2) DEFAULT NULL,
  `currency` varchar(255) NOT NULL DEFAULT 'USD',
  `description` text DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'Order Received',
  `customs_wait_started_at` datetime DEFAULT NULL,
  `customs_auction_deadline` datetime DEFAULT NULL,
  `customs_cleared_at` datetime DEFAULT NULL,
  `is_in_auction` tinyint(1) NOT NULL DEFAULT 0,
  `auction_notified_at` datetime DEFAULT NULL,
  `customs_notes` text DEFAULT NULL,
  `payment_status` varchar(255) NOT NULL DEFAULT 'Paid',
  `dispatch_date` date DEFAULT NULL,
  `estimated_delivery` date DEFAULT NULL,
  `actual_delivery` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `ref_no` varchar(255) DEFAULT NULL,
  `product_value` decimal(10,2) DEFAULT NULL,
  `billing_weight_kg` decimal(8,2) DEFAULT NULL,
  `billing_weight_gm` decimal(8,2) DEFAULT NULL,
  `gross_weight` decimal(8,2) DEFAULT NULL,
  `payment_mode` varchar(255) DEFAULT NULL,
  `bill_amount` decimal(10,2) DEFAULT NULL,
  `dollar_rate` decimal(10,2) DEFAULT NULL,
  `cod_amount` decimal(10,2) DEFAULT NULL,
  `item_type` varchar(255) DEFAULT NULL,
  `item_name` varchar(255) DEFAULT NULL,
  `item_description` text DEFAULT NULL,
  `length` decimal(8,2) DEFAULT NULL,
  `height` decimal(8,2) DEFAULT NULL,
  `width` decimal(8,2) DEFAULT NULL,
  `dimensional_weight_kg` decimal(8,2) DEFAULT NULL,
  `branch` varchar(255) DEFAULT NULL,
  `client` varchar(255) DEFAULT NULL,
  `hub` varchar(255) DEFAULT NULL,
  `usa_country_code` varchar(255) DEFAULT NULL,
  `flight` varchar(255) DEFAULT NULL,
  `services` varchar(255) DEFAULT NULL,
  `product_type` varchar(255) DEFAULT NULL,
  `money_receipt_no` varchar(255) DEFAULT NULL,
  `sender_attention` varchar(255) DEFAULT NULL,
  `sender_zip` varchar(255) DEFAULT NULL,
  `sender_origin_code` varchar(255) DEFAULT NULL,
  `shipper_code` varchar(50) DEFAULT NULL,
  `receiver_attention` varchar(255) DEFAULT NULL,
  `receiver_zip` varchar(255) DEFAULT NULL,
  `receiver_destination_code` varchar(255) DEFAULT NULL,
  `consignee_code` varchar(50) DEFAULT NULL,
  `booking_date` date DEFAULT NULL,
  `export_date` date DEFAULT NULL,
  `picked_up_by` varchar(255) DEFAULT NULL,
  `pickup_date_time` datetime DEFAULT NULL,
  `mawb_no` varchar(255) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `updated_by` varchar(255) DEFAULT NULL,
  `showing_weight_kgs` decimal(8,2) DEFAULT NULL,
  `showing_weight_gms` decimal(8,2) DEFAULT NULL,
  `showing_weight` decimal(8,2) DEFAULT NULL,
  `sales_by` varchar(255) DEFAULT NULL,
  `express_packaging_service` varchar(255) DEFAULT NULL,
  `packaging_type` varchar(255) DEFAULT NULL,
  `cke_iid` bigint(20) UNSIGNED DEFAULT NULL,
  `cke_ems_kind` varchar(30) DEFAULT NULL,
  `cke_waybill_no` varchar(50) DEFAULT NULL,
  `cke_label_url` varchar(500) DEFAULT NULL,
  `cke_sync_status` varchar(20) NOT NULL DEFAULT 'pending',
  `cke_sync_error` varchar(255) DEFAULT NULL,
  `cke_synced_at` datetime DEFAULT NULL,
  `cke_tracked_at` datetime DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `deleted_by` bigint(20) UNSIGNED DEFAULT NULL,
  `cke_delete_status` varchar(20) DEFAULT NULL,
  `cke_status` tinyint(4) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

